    reg [31:0] c = 0;
    reg [31:0] h = 0;
    reg [31:0] m = 0;
    reg [31:0] s = 0;
    always @(posedge clk) begin
        if (reset) begin
            c <= 0; h <= 0; m <= 0; s <= 0; pm <= 0;
        end else if (ena) begin
            c <= c + 1;
            if (c == 100000000) begin
                c <= 0;
                s <= s + 1;
