// One-hot to binary decoder
function [3:0] onehot2bin;
    input [3:0] onehot;
    case (onehot)
        4'b0001: onehot2bin = 4'd0;
        4'b0010: onehot2bin = 4'd1;
        4'b0100: onehot2bin = 4'd2;
        4'b1000: onehot2bin = 4'd3;
        4'b0011: onehot2bin = 4'd4;
        4'b0101: onehot2bin = 4'd5;
        4'b0110: onehot2bin = 4'd6;
        4'b1001: onehot2bin = 4'd7;
        4'b0111: onehot2bin = 4'd8;
        4'b1000: onehot2bin = 4'd9;
        default: onehot2bin = 4'd10;
    endcase
endfunction

// Binary to BCD function
function [7:0] bin2bcd;
    input [7:0] bin;
    reg [7:0] bcd;
    integer i;
    begin
        bcd = 8'd0;
        for (i = 0; i < 8; i = i + 1) begin
            if (((bcd >> 4) > 4) || ((bcd >> 4) == 4 && (bcd & 15) > 9))
                bcd = bcd + 8'd6;
            if (((bcd >> 4) > 9) || ((bcd >> 4) == 9 && (bcd & 15) > 9))
                bcd = bcd + 8'd6;
            bcd = {bcd[6:0], bin[7]};
            bin = {bin[6:0], 1'b0};
        end
    end
    bin2bcd = bcd;
endfunction

