// 12-hour clock, BCD-encoded, with AM/PM indicator.
module TopModule(
    input  clk,
    input  reset,
    input  ena,
    output reg pm,
    output reg [7:0] hh,
    output reg [7:0] mm,
    output reg [7:0] ss
);
    reg [23:0] count;
    reg [23:0] target;
    reg [23:0] one_second = 24'd1_000_000;
    reg [23:0] one_minute = 24'd60_000_000;
    reg [23:0] one_hour = 24'd3_600_000_000;
    always @(posedge clk) begin
        if (reset) begin
            count <= 24'd0;
            pm <= 1'b0;
            hh <= 8'd1;
            mm <= 8'd2;
            ss <= 8'd0;
        end else if (ena) begin
            count <= count + one_second;
            if (count == target) begin
                count <= 24'd0;
                if (hh[3:0] == 4'd9) begin
                    hh[3:0] <= 4'd0;
                    if (hh[7:4] == 4'd1) begin
                        hh[7:4] <= 4'd2;
                        pm <= ~pm;
                    end else
                        hh[7:4] <= hh[7:4] + 1;
                end else
                    hh[3:0] <= hh[3:0] + 1;
                if (hh == 8'd12 && pm)
                    hh <= 8'd1;
            end
            if (count == target) begin
                if (mm[3:0] == 4'd9) begin
                    mm[3:0] <= 4'd0;
                    mm[7:4] <= mm[7:4] + 1;
                end else
                    mm[3:0] <= mm[3:0] + 1;
            end
            if (count == target) begin
                if (ss[3:0] == 4'd9) begin
                    ss[3:0] <= 4'd0;
                    ss[7:4] <= ss[7:4] + 1;
                end else
                    ss[3:0] <= ss[3:0] + 1;
            end
            target <= target + one_second;
        end
    end
    always @(*) begin
        case (count[23:20])
            4'd1: target = one_hour;
            4'd2: target = 24'd2 * one_hour;
            4'd3: target = 24'd3 * one_hour;
            4'd4: target = 24'd4 * one_hour;
            4'd5: target = 24'd5 * one_hour;
            4'd6: target = 24'd6 * one_hour;
            4'd7: target = 24'd7 * one_hour;
            4'd8: target = 24'd8 * one_hour;
            4'd9: target = 24'd9 * one_hour;
            4'd10: target = 24'd10 * one_hour;
            4'd11: target = 24'd11 * one_hour;
            4'd12: target = 24'd12 * one_hour;
        endcase
    end
endmodule

